import {
  createContext,
  useContext,
  ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';
import { useConvexAuth, useQuery, useMutation } from 'convex/react';
import { useAuthActions } from '@convex-dev/auth/react';
import { api } from 'convex/_generated/api';
import { useLocation } from 'wouter';
import { Loader2 } from 'lucide-react';
import { GOOGLE_OAUTH_SETTLE_TIMEOUT_MS } from '@/lib/auth/oauthCallback';

interface User {
  _id: string;
  email?: string;
  name?: string;
  image?: string;
  age?: number;
  ageGroup?: '8-14' | '15-20' | '21-65';
  location?: string;
  assessmentStarted?: boolean;
  needsProfileCompletion?: boolean;
  isPaid?: boolean;
  preAssessmentCompleted?: boolean;
  assessmentCompleted?: boolean;
}

interface AuthContext {
  /** Resolved profile from users.viewer. Null when logged out or no row yet. */
  user: User | null;
  /** Convex Auth (JWT/session) initializing. */
  isLoading: boolean;
  /** Convex Auth hook loading only (excludes OAuth callback settling). */
  isConvexAuthLoading: boolean;
  /** Drop OAuth settling timers/state after URL/session cleanup (Google callback paths). */
  clearOAuthCallbackSettling: () => void;
  /** True when JWT says signed-in but users.viewer has not settled (query still pending). */
  isViewerLoading: boolean;
  isAuthenticated: boolean;
  signIn: ReturnType<typeof useAuthActions>['signIn'];
  signOut: () => Promise<void>;
  isSavingBeforeLogout: boolean;
}

const AuthContext = createContext<AuthContext | undefined>(undefined);

function getDashboardLaneForAgeGroup(ageGroup?: User['ageGroup']) {
  if (ageGroup === '8-14') return '/spiral-the-study-buddy';
  if (ageGroup === '15-20' || ageGroup === '21-65') return '/career-hub';
  return '/dashboard';
}

interface AuthContextProviderProps {
  children: ReactNode;
}

export function AuthContextProvider({ children }: AuthContextProviderProps) {
  const { isAuthenticated, isLoading: isConvexAuthLoading } = useConvexAuth();
  const { signIn, signOut: convexSignOut } = useAuthActions();
  const viewer = useQuery(api.users.viewer);
  const userValue = viewer === undefined ? null : viewer;
  const isViewerLoading = isAuthenticated && viewer === undefined;
  const [location, setLocation] = useLocation();
  const [isSavingBeforeLogout, setIsSavingBeforeLogout] = useState(false);
  const [showSaveError, setShowSaveError] = useState(false);
  const [isOAuthCallbackSettling, setIsOAuthCallbackSettling] = useState(false);
  const isLoading = isConvexAuthLoading || isOAuthCallbackSettling;
  const oauthSettlingTimersRef = useRef<{
    start?: number;
    stop?: number;
  }>({});

  const clearOAuthTimersOnly = () => {
    if (typeof window === 'undefined') return;
    const r = oauthSettlingTimersRef.current;
    if (r.start !== undefined) window.clearTimeout(r.start);
    if (r.stop !== undefined) window.clearTimeout(r.stop);
    oauthSettlingTimersRef.current = {};
  };

  const clearOAuthCallbackSettling = useCallback(() => {
    clearOAuthTimersOnly();
    setIsOAuthCallbackSettling(false);
  }, []);

  // Query for partial assessment
  const partialAssessment = useQuery(api.partialAssessments.getForUser);

  // Mutation to save partial assessment
  const savePartialAssessment = useMutation(api.partialAssessments.savePartialAssessment);

  // Retry wrapper with exponential backoff
  const savePartialAssessmentWithRetry = async (
    args: Parameters<typeof savePartialAssessment>[0],
    maxRetries = 3,
  ) => {
    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        console.log(`[Logout Save] Attempt ${attempt}/${maxRetries}`);
        const result = await savePartialAssessment(args);
        return result;
      } catch (error) {
        console.error(`[Logout Save] Attempt ${attempt} failed:`, error);
        if (attempt === maxRetries) {
          throw error;
        }
        const delay = Math.pow(2, attempt - 1) * 500; // 500ms, 1000ms
        console.log(`[Logout Save] Retrying in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  };

  const signOut = async () => {
    const hasIncompleteAssessment =
      userValue?.needsProfileCompletion === true && partialAssessment?.answers;

    if (hasIncompleteAssessment) {
      setIsSavingBeforeLogout(true);
      const startTime = performance.now();

      try {
        console.log('[Logout Save] Starting save attempt...');
        const saveStartTime = performance.now();

        // Race between save with retries and timeout
        await Promise.race([
          savePartialAssessmentWithRetry({
            answers: partialAssessment.answers || {},
            currentIndex: partialAssessment.currentIndex || 0,
            currentStage: partialAssessment.currentStage || 'questions',
          }),
          new Promise((_, reject) =>
            setTimeout(() => reject(new Error('Save timeout after 5 seconds')), 5000)
          )
        ]);

        const saveEndTime = performance.now();
        const saveDuration = saveEndTime - saveStartTime;
        console.log(`[Logout Save] Save completed successfully in ${saveDuration.toFixed(0)}ms`);

        await new Promise(resolve => setTimeout(resolve, 500));
        const totalTime = performance.now() - startTime;
        console.log(`[Logout Save] Total logout save process: ${totalTime.toFixed(0)}ms`);

      } catch (error) {
        const failedTime = performance.now() - startTime;
        console.error(`[Logout Save] All retries failed after ${failedTime.toFixed(0)}ms:`, error);

        setShowSaveError(true);
        await new Promise(resolve => setTimeout(resolve, 3000));
        setShowSaveError(false);
      } finally {
        setIsSavingBeforeLogout(false);
      }
    }

    await convexSignOut();
    setLocation('/');
  };

  useEffect(() => {
    const onClear = () => clearOAuthCallbackSettling();
    window.addEventListener('txai-clear-oauth-settling', onClear);
    return () => window.removeEventListener('txai-clear-oauth-settling', onClear);
  }, [clearOAuthCallbackSettling]);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const params = new URLSearchParams(window.location.search);
    const isGoogleOAuthReturn =
      params.get("oauth") === "google" &&
      params.get("oauthError") !== "google_callback_failed";
    const isGoogleOAuthInFlight =
      window.sessionStorage.getItem("txaiGoogleOAuthInFlight") === "1";
    const shouldWaitForOAuthSession =
      !isAuthenticated && isGoogleOAuthReturn && isGoogleOAuthInFlight;

    if (!shouldWaitForOAuthSession) {
      clearOAuthTimersOnly();
      const timeout = window.setTimeout(() => {
        setIsOAuthCallbackSettling(false);
      }, 0);
      return () => {
        window.clearTimeout(timeout);
      };
    }

    clearOAuthTimersOnly();
    oauthSettlingTimersRef.current.start = window.setTimeout(() => {
      setIsOAuthCallbackSettling(true);
    }, 0);
    oauthSettlingTimersRef.current.stop = window.setTimeout(() => {
      clearOAuthCallbackSettling();
    }, GOOGLE_OAUTH_SETTLE_TIMEOUT_MS);

    return () => {
      clearOAuthTimersOnly();
    };
  }, [isAuthenticated, location, clearOAuthCallbackSettling]);

  useEffect(() => {
    if (isLoading || !isAuthenticated || isViewerLoading) return;

    const needsPreAssessment =
      userValue?.needsProfileCompletion !== true &&
      userValue?.preAssessmentCompleted !== true;
    const completedDashboardLane = getDashboardLaneForAgeGroup(
      userValue?.ageGroup,
    );
    const hasPartialAssessment =
      !!partialAssessment?.answers &&
      Object.keys(partialAssessment.answers as Record<string, unknown>).length > 0;

    const completionBridgeActive = (() => {
      if (typeof window === 'undefined') return false;
      const raw = sessionStorage.getItem('tx_assessment_completion_bridge');
      if (!raw) return false;
      try {
        const parsed = JSON.parse(raw) as { completedAt?: number };
        if (!parsed?.completedAt) return false;
        // Bridge is temporary and only valid during client hydration.
        return Date.now() - parsed.completedAt < 10 * 60 * 1000;
      } catch {
        return false;
      }
    })();

    const allowAssessmentBypassDuringHydration =
      needsPreAssessment && completionBridgeActive;

    // If the assessment write just completed but viewer flags have not
    // refreshed yet, route forward instead of looping back into assessment.
    if (allowAssessmentBypassDuringHydration) {
      if (location === '/matching-preview' || location === '/discover' || location === '/assessment-21-65') {
        setLocation(completedDashboardLane);
      }
      return;
    }

    // If user still needs pre-assessment and has a saved partial attempt,
    // continue from matching-preview.
    if (needsPreAssessment && hasPartialAssessment) {
      sessionStorage.removeItem('redirectAfterLogin');
      if (location !== '/discover' && location !== '/' && !location.startsWith('/auth') && location !== '/upgrade' && location !== '/pricing') {
        setLocation('/discover');
      }
      return;
    }

    // Otherwise, send incomplete users to the canonical discover assessment.
    if (needsPreAssessment) {
      sessionStorage.removeItem('redirectAfterLogin');
      if (location !== '/discover' && location !== '/' && !location.startsWith('/auth') && location !== '/upgrade' && location !== '/pricing') {
        setLocation('/discover');
      }
      return;
    }

    if (!needsPreAssessment && typeof window !== 'undefined') {
      sessionStorage.removeItem('tx_assessment_completion_bridge');
    }

    // If they land on matching-preview but have already completed it, move them to the dashboard.
    if (!needsPreAssessment && location === '/matching-preview') {
      setLocation('/dashboard');
      return;
    }

    // If there is a stored redirect (set before login), honor it once.
    const stored = sessionStorage.getItem('redirectAfterLogin');
    if (stored) {
      sessionStorage.removeItem('redirectAfterLogin');
      if (location !== stored) {
        setLocation(stored);
      }
    }
  }, [
    isAuthenticated,
    isLoading,
    isViewerLoading,
    location,
    setLocation,
    partialAssessment,
    userValue?.needsProfileCompletion,
    userValue?.preAssessmentCompleted,
    userValue?.assessmentStarted,
  ]);

  const value: AuthContext = {
    user: userValue,
    isLoading,
    isConvexAuthLoading,
    clearOAuthCallbackSettling,
    isViewerLoading,
    isAuthenticated,
    signIn,
    signOut,
    isSavingBeforeLogout,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}

      {/* Saving modal during logout */}
      {isSavingBeforeLogout && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-8 max-w-md mx-4 text-center">
            <div className="flex justify-center mb-4">
              <Loader2 className="h-12 w-12 animate-spin text-primary" />
            </div>
            <h3 className="text-xl font-semibold mb-2 text-gray-900 dark:text-white">
              Saving Your Progress
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              Please wait while we save your assessment progress...
            </p>
          </div>
        </div>
      )}

      {/* Error modal if save fails */}
      {showSaveError && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-8 max-w-md mx-4 text-center">
            <div className="flex justify-center mb-4">
              <div className="h-12 w-12 rounded-full bg-yellow-100 dark:bg-yellow-900/20 flex items-center justify-center">
                <span className="text-2xl">⚠️</span>
              </div>
            </div>
            <h3 className="text-xl font-semibold mb-2 text-gray-900 dark:text-white">
              Unable to Save Progress
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mb-2">
              We couldn't save your latest progress, but your previous answers are still preserved.
            </p>
            <p className="text-sm text-gray-500 dark:text-gray-500">
              Logging you out now...
            </p>
          </div>
        </div>
      )}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthContextProvider');
  }
  return context;
}

import { getAuthUserId } from "@convex-dev/auth/server";
import { v } from "convex/values";
import { mutation, query } from "./_generated/server";
import type { Id } from "./_generated/dataModel";
import { writeWristbandHard } from "./lib/wristband";
import { QUESTIONS } from "./lib/assessment21_65/questions";
import {
  buildAssessment2165Result,
  type Assessment2165Answer,
} from "./lib/assessment21_65/scoring";

function promptScoreFromCcit(ccit: { clarity: number; constraints: number; iteration: number; tool: number }) {
  return Math.round(ccit.clarity + ccit.constraints + ccit.iteration + ccit.tool);
}

function skillsFromResult(result: ReturnType<typeof buildAssessment2165Result>) {
  return {
    generative_ai: result.aiAptitude.prompting,
    agentic_ai: result.aiAptitude.agentic,
    synthetic_ai: result.aiAptitude.systems,
    coding: Math.round(result.vector.aiAptitude.systems * 100),
    agi_readiness: Math.round(
      ((result.vector.aiAptitude.prompting +
        result.vector.aiAptitude.agentic +
        result.vector.aiAptitude.systems) /
        3) *
        100,
    ),
    communication: Math.round(result.vector.bigFive.agreeableness * 100),
    logic: Math.round(result.vector.riasec.investigative * 100),
    planning: Math.round(result.vector.lifeSkills.timeManagement * 100),
    analysis: Math.round(result.vector.riasec.conventional * 100),
    creativity: Math.round(result.vector.riasec.artistic * 100),
    collaboration: Math.round(result.vector.riasec.social * 100),
  };
}

function flatMarkers(result: ReturnType<typeof buildAssessment2165Result>) {
  return {
    ...Object.fromEntries(Object.entries(result.vector.bigFive).map(([key, value]) => [`bigFive.${key}`, value])),
    ...Object.fromEntries(Object.entries(result.vector.riasec).map(([key, value]) => [`riasec.${key}`, value])),
    ...Object.fromEntries(Object.entries(result.vector.aiAptitude).map(([key, value]) => [`aiAptitude.${key}`, value])),
    ...Object.fromEntries(Object.entries(result.vector.ccit).map(([key, value]) => [`ccit.${key}`, value])),
    ...Object.fromEntries(Object.entries(result.vector.lifeSkills).map(([key, value]) => [`lifeSkills.${key}`, value])),
  };
}

function initialUserStats(userId: Id<"users">, result: ReturnType<typeof buildAssessment2165Result>) {
  return {
    userId,
    promptScore: promptScoreFromCcit(result.ccit),
    previousPromptScore: 0,
    communityScore: 0,
    totalScore: promptScoreFromCcit(result.ccit),
    rubric: result.ccit,
    skills: skillsFromResult(result),
    badges: [],
    completedProjects: [],
    assessmentHistory: [{ date: new Date(result.completedAt).toISOString(), promptScore: promptScoreFromCcit(result.ccit), skills: skillsFromResult(result), rubric: result.ccit }],
    streak: 0,
    lastActiveDate: Date.now(),
    assessmentComplete: true,
    ageGroup: "21-65" as const,
    assessmentCompleted: true,
    assessmentCompletedAt: result.completedAt,
    assessmentProgress: 100,
    assessmentResults: result,
    unlockedCareers: [],
    weeklyPracticeMinutes: 0,
    communityActivity: {
      postsCreated: 0,
      upvotesReceived: 0,
      downvotesReceived: 0,
      helpfulAnswers: 0,
      communityScore: 0,
    },
    preAssessmentCompleted: true,
    baselineAssessmentSnapshot: {
      markers: flatMarkers(result),
      dialScores: result.ccit,
      overallScore: promptScoreFromCcit(result.ccit),
      ageMode: "21-65",
      completedAt: result.completedAt,
      version: 1,
    },
    pathwayFitScores: Object.fromEntries(
      result.pathways.map((pathway) => [pathway.pathway, pathway.match]),
    ),
    strengths: [...result.hardSkills, ...result.softSkills].slice(0, 5),
    growthAreas: [],
    profileLastUpdatedAt: result.completedAt,
    profileVersion: 1,
  };
}

export const getQuestions = query({
  args: {},
  handler: async () => {
    return QUESTIONS.map((question, index) => ({
      id: question.id,
      number: index + 1,
      stem: question.stem,
      leftLabel: question.leftLabel,
      rightLabel: question.rightLabel,
      leftImageId: question.leftImageId,
      rightImageId: question.rightImageId,
      leftImageSpec: question.leftImageSpec,
      rightImageSpec: question.rightImageSpec,
      totalQuestions: QUESTIONS.length,
    }));
  },
});

export const submit = mutation({
  args: {
    answers: v.array(
      v.object({
        questionId: v.string(),
        choice: v.union(v.literal("left"), v.literal("right")),
      }),
    ),
  },
  handler: async (ctx, args) => {
    const userId = await getAuthUserId(ctx);
    if (!userId) throw new Error("Unauthenticated");

    const answers = args.answers as Assessment2165Answer[];
    const result = buildAssessment2165Result(answers);
    const promptScore = promptScoreFromCcit(result.ccit);
    const skills = skillsFromResult(result);

    await ctx.db.patch(userId, {
      ageGroup: "21-65",
      assessmentStarted: true,
      assessmentCompleted: true,
      assessmentCompletedAt: result.completedAt,
      assessmentProgress: 100,
      preAssessmentCompleted: true,
      needsProfileCompletion: false,
      recommendedPath: result.pathways[0]?.pathway,
      assessmentResults: result,
    });

    const stats = await ctx.db
      .query("userStats")
      .withIndex("by_user", (q) => q.eq("userId", userId))
      .first();

    if (stats) {
      await ctx.db.patch(stats._id, {
        previousPromptScore: stats.promptScore,
        promptScore,
        totalScore: promptScore + (stats.communityScore ?? 0),
        rubric: result.ccit,
        skills,
        assessmentComplete: true,
        ageGroup: "21-65",
        assessmentCompleted: true,
        assessmentCompletedAt: result.completedAt,
        assessmentProgress: 100,
        assessmentResults: result,
        preAssessmentCompleted: true,
        baselineAssessmentSnapshot: {
          markers: flatMarkers(result),
          dialScores: result.ccit,
          overallScore: promptScore,
          ageMode: "21-65",
          completedAt: result.completedAt,
          previousScoreRef: stats.promptScore,
          version: 1,
        },
        pathwayFitScores: Object.fromEntries(
          result.pathways.map((pathway) => [pathway.pathway, pathway.match]),
        ),
        strengths: [...result.hardSkills, ...result.softSkills].slice(0, 5),
        profileLastUpdatedAt: result.completedAt,
        profileVersion: (stats.profileVersion ?? 0) + 1,
        assessmentHistory: [
          ...(stats.assessmentHistory ?? []),
          { date: new Date(result.completedAt).toISOString(), promptScore, skills, rubric: result.ccit },
        ].slice(-10),
      });
    } else {
      await ctx.db.insert("userStats", initialUserStats(userId, result));
    }

    await writeWristbandHard(ctx, userId, result.ccit, "assessment-21-65", {
      ageGroup: "21-65",
      learningStyle: result.learningStyle,
      personalityType: result.personalityType,
      hardSkills: result.hardSkills,
      softSkills: result.softSkills,
      aiAptitude: result.aiAptitude,
      partialReportUnlocked: true,
      consentGiven: true,
    });

    const partial = await ctx.db
      .query("partialAssessments")
      .withIndex("by_user", (q) => q.eq("userId", userId))
      .first();
    if (partial) await ctx.db.delete(partial._id);

    await ctx.db.insert("quizResults", {
      userId,
      quizType: "assessment_21_65",
      answers,
      results: result,
      completedAt: result.completedAt,
    });

    return {
      topPathway: result.pathways[0]?.pathway ?? "AI Career",
      pathwayLabel: result.pathways[0]?.match >= 0.75 ? "strong match" : "growing match",
      completedAt: result.completedAt,
    };
  },
});

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

/**
 * Convex Auth stores the session in httpOnly cookies consumed by ConvexReactClient
 * in the browser. Server middleware cannot reliably validate those tokens without
 * duplicating @convex-dev/auth internals, so authenticated routing stays in
 * AuthContextProvider, dashboard layouts, and RouteGuard.
 *
 * Keep this passthrough explicit so deployments do not assume an Edge JWT gate exists.
 */
export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Phase 1: retired duplicate `/assessment-lite` App Router segment; canonical path is `/assessment`.
  if (pathname === "/assessment-lite" || pathname.startsWith("/assessment-lite/")) {
    const rest =
      pathname === "/assessment-lite" ? "" : pathname.slice("/assessment-lite".length);
    const url = request.nextUrl.clone();
    url.pathname = `/assessment${rest}`;
    return NextResponse.redirect(url, 301);
  }

  return NextResponse.next();
}

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

// INTERNAL SCORING IS NEVER EXPOSED TO USERS. Show outcomes only -
// 'profile updated', 'you improved in X', 'new matches unlocked',
// 'X% to next pathway', 'certificate earned'. Never expose CCIT scores,
// Wristband logic, IDs, formulas, or score sources. Apple-style
// invisible genius. Apply across every page forever.

import { Assessment2165Flow } from "@/components/assessment/Assessment2165Flow";

export default function DiscoverPage() {
  return <Assessment2165Flow />;
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";

// /career-hub is the canonical, branded entry that resolves to the live
// Career Hub render at /ai-database. Server-side `redirect()` from
// next/navigation can leak a Next redirect/error shell on static fetch
// (prefetch + RSC race). Use a client-side replace inside useEffect with
// a minimal placeholder so the route always returns a clean HTTP 200
// shell and the redirect happens after hydration.
export default function CareerHubRoute() {
  const router = useRouter();
  useEffect(() => {
    router.replace("/ai-database");
  }, [router]);
  return (
    <div className="flex min-h-screen items-center justify-center bg-white">
      <p className="text-sm font-medium" style={{ color: "#303030", opacity: 0.7 }}>
        Opening Career Hub.
      </p>
    </div>
  );
}

"use client";

import { ResetPasswordWithEmailCode } from "@/components/auth/ResetPasswordWithEmailCode";
import { SignInMethodDivider } from "@/components/auth/SignInMethodDivider";
import { UnsafeOAuthEnvironmentNotice } from "@/components/auth/UnsafeOAuthEnvironmentNotice";
import { SignInWithGoogle } from "@/components/auth/oauth/SignInWithGoogle";
import { SignInWithPassword } from "@/components/auth/SignInWithPassword";
import { CodeInput } from "@/components/auth/CodeInput";
import { Button } from "@/components/ui/button";
import { Toaster } from "@/components/ui/toaster";
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContextProvider";
import { useLocation } from "wouter";
import { useAuthActions } from "@convex-dev/auth/react";
import {
  buildOpenInBrowserUrl,
  useOAuthEnvironment,
} from "@/lib/auth/oauthEnvironment";
import {
  GOOGLE_OAUTH_SETTLE_TIMEOUT_MS,
  isGoogleOAuthReturnWithoutCode,
} from "@/lib/auth/oauthCallback";
import toast from "react-hot-toast";

export default function AuthPage() {
  const [step, setStep] = useState<"signIn" | { email: string } | "forgot">(
    "signIn"
  );
  const {
    isAuthenticated,
    isLoading,
    isConvexAuthLoading,
    clearOAuthCallbackSettling,
    isViewerLoading,
    user,
  } = useAuth();
  const [, setLocation] = useLocation();
  const { signIn, signOut } = useAuthActions();
  const oauthEnvironment = useOAuthEnvironment();
  const [submitting, setSubmitting] = useState(false);
  const [awaitingVerification, setAwaitingVerification] = useState(false);
  const [justCancelledVerification, setJustCancelledVerification] = useState(false);
  const openInBrowserUrl = buildOpenInBrowserUrl({
    currentHref: typeof window !== "undefined" ? window.location.href : undefined,
  });

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("oauthError") !== "google_callback_failed") return;
    clearOAuthCallbackSettling();
    const detail = sessionStorage.getItem("txaiGoogleOAuthError");
    sessionStorage.removeItem("txaiGoogleOAuthError");
    toast.error(
      detail
        ? `Google sign-in failed: ${detail}`
        : "Google sign-in failed during callback. Please try again.",
    );
    window.history.replaceState(null, "", "/auth");
  }, [clearOAuthCallbackSettling]);

  useEffect(() => {
    if (isConvexAuthLoading || isAuthenticated) return;
    const googleCallbackReturnedWithoutCode = isGoogleOAuthReturnWithoutCode(
      window.location.search,
      sessionStorage.getItem("txaiGoogleOAuthInFlight") === "1",
    );

