];

const ALWAYS_PROTECTED_ROUTE_PREFIXES = [
  "/admin",
  "/owner",
  "/trainer",
  "/billing",
  "/api",
  "/upgrade",
  "/pricing",
];

function matchesPrefix(pathname: string, prefix: string) {
  return pathname === prefix || pathname.startsWith(`${prefix}/`);
}

function getConfiguredAppHost() {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL;
  if (!appUrl) return "";
  try {
    return new URL(appUrl).hostname.toLowerCase();
  } catch {
    return "";
  }
}

export function isTemporaryStagingAuthBypassEnabled(pathname: string) {
  // TEMPORARY STAGING AUTH BYPASS: remove after Google OAuth is verified on mobile.
  if (process.env.NEXT_PUBLIC_AUTH_BYPASS !== "true") return false;
  if (ALWAYS_PROTECTED_ROUTE_PREFIXES.some((prefix) => matchesPrefix(pathname, prefix))) {
    return false;
  }
  if (!BYPASSABLE_ROUTE_PREFIXES.some((prefix) => matchesPrefix(pathname, prefix))) {
    return false;
  }
  if (typeof window === "undefined") return false;

  const host = window.location.hostname;
  const extra =
    (process.env.NEXT_PUBLIC_AUTH_BYPASS_HOSTS ?? "")
      .split(",")
      .map((h) => h.trim().toLowerCase())
      .filter(Boolean);
  const appHost = getConfiguredAppHost();
  const allowed = new Set<string>(["localhost", "127.0.0.1", appHost, ...extra].filter(Boolean));
  return allowed.has(host.toLowerCase());
}

