export function Assessment2165Flow() {
  const router = useRouter();
  const { isAuthenticated, isLoading } = useAuth();
  const questions = useQuery(api.assessment2165.getQuestions) as PublicQuestion[] | undefined;
  const partialAssessment = useQuery(api.partialAssessments.getForUser);
  const savePartialAssessment = useMutation(api.partialAssessments.savePartialAssessment);
  const submitAssessment = useMutation(api.assessment2165.submit);

  const [answers, setAnswers] = useState<AnswerMap>({});
  const [currentIndex, setCurrentIndex] = useState(0);
  const hydratedRef = useRef(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) router.replace("/auth");
  }, [isAuthenticated, isLoading, router]);

  useEffect(() => {
    if (hydratedRef.current || !partialAssessment || !questions?.length) return;
    hydratedRef.current = true;
    if (partialAssessment.currentStage !== "assessment-21-65") {
      return;
    }

    const timeout = window.setTimeout(() => {
      const savedAnswers = partialAssessment.answers as AnswerMap;
      setAnswers(savedAnswers ?? {});
      setCurrentIndex(
        Math.min(Math.max(partialAssessment.currentIndex ?? 0, 0), questions.length - 1),
      );
    }, 0);
    return () => window.clearTimeout(timeout);
  }, [partialAssessment, questions]);

  const question = questions?.[currentIndex];
  const progress = questions?.length ? ((currentIndex + 1) / questions.length) * 100 : 0;
  const selected = question ? answers[question.id] : undefined;

  const answerList = useMemo(() => {
    if (!questions) return [];
    return questions
      .filter((item) => answers[item.id])
      .map((item) => ({ questionId: item.id, choice: answers[item.id] }));
  }, [answers, questions]);

  const persistProgress = async (nextAnswers: AnswerMap, nextIndex: number) => {
    try {
      await savePartialAssessment({
        answers: nextAnswers,
        currentIndex: nextIndex,
        currentStage: "assessment-21-65",
      });
    } catch {
      // Non-blocking. Final submit remains authoritative.
    }
  };

  const handleAnswer = async (choice: Choice) => {
    if (!question || !questions) return;
    const nextAnswers = { ...answers, [question.id]: choice };
    setAnswers(nextAnswers);

    const isLast = currentIndex === questions.length - 1;
    if (!isLast) {
      const nextIndex = currentIndex + 1;
      setCurrentIndex(nextIndex);
      void persistProgress(nextAnswers, nextIndex);
      return;
    }

    if (Object.keys(nextAnswers).length !== questions.length) {
      toast.error("Answer every question before finishing.");
      return;
    }

    setSubmitting(true);
    try {
      await submitAssessment({
        answers: questions.map((item) => ({ questionId: item.id, choice: nextAnswers[item.id] })),
      });
      sessionStorage.setItem(
        "tx_assessment_completion_bridge",
        JSON.stringify({ completedAt: Date.now(), route: "/career-hub" }),
      );
      toast.success("Profile updated. New matches unlocked.");
      router.replace("/career-hub");
    } catch (error) {
      console.error(error);
      toast.error("Assessment could not be saved. Try again.");
      setSubmitting(false);
    }
  };

  const handleBack = () => {
    const nextIndex = Math.max(0, currentIndex - 1);
    setCurrentIndex(nextIndex);
    void persistProgress(answers, nextIndex);
  };

  if (isLoading || !questions || !question) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-50">
        <Loader2 className="h-8 w-8 animate-spin text-emerald-600" />
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-50 px-4 py-6 sm:px-6">
      <div className="mx-auto flex min-h-[calc(100vh-3rem)] max-w-5xl flex-col">
        <header className="mb-6 space-y-4">
          <div className="flex items-center justify-between gap-4">
            <Button
              type="button"
              variant="ghost"
              onClick={handleBack}
              disabled={currentIndex === 0 || submitting}
            >
              <ArrowLeft className="h-4 w-4" /> Back
            </Button>
            <div className="text-sm font-medium text-slate-600">
              {currentIndex + 1} of {questions.length}
            </div>
          </div>
          <Progress value={progress} className="h-2" />
          <p className="text-center text-xs text-slate-500">{PROFILE_COPY}</p>
        </header>

        <section className="flex flex-1 items-center">
          <Card className="w-full border-slate-200 shadow-sm">
            <CardContent className="p-5 sm:p-8">
              <div className="mb-7 text-center">
                <div className="mb-3 inline-flex items-center rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700">
                  <Sparkles className="mr-1 h-3.5 w-3.5" /> Choose what fits you best
                </div>
                <h1 className="text-2xl font-bold text-slate-950 sm:text-3xl">
                  {question.stem}
                </h1>
              </div>

              <div className="grid gap-4 md:grid-cols-2">
                <SceneCard
                  label={question.leftLabel ?? "Option A"}
                  spec={question.leftImageSpec}
                  selected={selected === "left"}
                  onSelect={() => void handleAnswer("left")}
                />
                <SceneCard
                  label={question.rightLabel ?? "Option B"}
                  spec={question.rightImageSpec}
                  selected={selected === "right"}
                  onSelect={() => void handleAnswer("right")}
                />
              </div>

              <div className="mt-6 flex items-center justify-between text-sm text-slate-500">
                <span>{answerList.length} answered</span>
                {submitting ? <span>Saving your profile...</span> : <span>Tap one card to continue</span>}
              </div>
            </CardContent>
          </Card>
        </section>
      </div>
    </main>
  );
}

